function homeEditSummary(p){const s=p.summary,status=s?.lastEditStatus||'pending',event=s?.lastEdit;if(status==='available'&&event){const date=new Date(event.at),kind=event.kind==='confirm'?'원본 Confirm':'초안 Save';return `<time data-stat="lastEdit" data-status="available" datetime="${esc(event.at)}" title="${esc(kind+' 성공 · '+event.at+' · 기록 이후의 저장된 소스 편집')}">${esc(date.toLocaleString())}</time>`;}return `<span data-stat="lastEdit" data-status="${esc(status)}" title="${status==='none'?'편집 기록이 없습니다. 기록 도입 전 편집이나 미저장 입력의 시각은 추측하지 않습니다.':'편집 기록을 읽을 수 없습니다.'}">${status==='none'?'기록 없음':'—'}</span>`;}
