// Reopen read-only view ownership through the existing idempotent contract.
// Only an unexecuted transport revision rejection is retried; source CAS is untouched.
async function restoreWorkspaceBindings(bindings,id){
 if(busy)throw Error('view_busy');busy=true;controls();
 const read=async(endpoint,input)=>{for(let attempt=0;attempt<3;attempt++){await view.update();try{return await view.call(endpoint,input);}catch(error){if(error.message!=='stale_revision'||attempt===2)throw error;}}};
 try{if(id&&current.draft?.id!==id){await read('select',{id});if(['object','schema'].includes(current.draft?.kind))await read('schema',{id});else if(!['body','blueprint','blueprint-node','project','pack'].includes(current.draft?.kind))await read('inspectDeclaration',{id});}for(const binding of bindings)await read('openEditorView',{view:binding.view,id:binding.id,viewMode:binding.mode});renderEditorViews();for(const binding of bindings)if(!current.editorViews.some(row=>row.view===binding.view&&row.id===binding.id&&row.mode===binding.mode))throw Error('view_recovery_failed');}
 finally{busy=false;controls();}
}
function recover(){if(!recovering)recovering=(async()=>{
 const wasBusy=busy;busy=true;controls();
 try{keepInput();await view.dispose();for(let attempt=0;;attempt++){try{await view.mount();break;}catch(error){if(error.message!=='busy'||attempt===99)throw error;await new Promise(resolve=>setTimeout(resolve,50));}}
  if($('.modal[data-helper-settings]')){const expanded=$('.helper-local-settings')?.open;showHelpers();if(expanded)$('.helper-local-settings').open=true;}
 }finally{busy=wasBusy;controls();}
})().finally(()=>recovering=null);return recovering;}

