// A stored configuration is not evidence that this person has connected an account.
// Keep automatic readiness, preparation and explicitly attempted login failures distinct.
function codexLoginPresentation(savedFlow,agent,readinessAttempted=false){
 const knownAccount=/^[a-f0-9]{64}$/.test(agent?.accountIdentity?.fingerprint||''),status=agent?.readiness;
 const registeredFlow=!!status&&['idle','cancelled','ready'].includes(savedFlow.state);
 let flow={...savedFlow};
 if(registeredFlow){
  if(!knownAccount)flow={state:'idle',message:'로그인해 사용할 계정을 확인하고 연결해 주세요.'};
  else flow={state:['ready','offline'].includes(status.state)?'ready':status.state==='checking'?'checking':'connection-blocked',message:status.message,model:agent.model,accountIdentity:agent.accountIdentity,code:status.code,retryable:!['unverified','account-mismatch'].includes(status.state),canLogin:['auth-required','account-mismatch','unverified'].includes(status.state),failureAction:'connection',readinessAttempted,diagnostics:['ready','offline','checking'].includes(status.state)?null:{code:status.code}};
 }
 if(flow.state==='failed'&&(!flow.failureAction||flow.failureAction==='setup')){
  flow.state='preparation-blocked';flow.message=(flow.loginAttempted===false?'로그인은 아직 시작하지 않았어요. ':'연결 준비를 확인해 주세요. ')+(flow.message||'Codex 연결 준비를 확인해 주세요.');
 }else if(flow.state==='failed'&&flow.failureAction==='connection'&&flow.loginCompleted){
  flow.message='로그인 절차는 끝났어요. '+(flow.message||'연결 준비를 확인해 주세요.');
 }
 return {flow,knownAccount,registeredFlow};
}
