  if(outcome.preflightRequirements?.length&&outcome.state!=='verified'&&outcome.state!=='checking'){
   result.insertAdjacentHTML('beforeend','<h4>'+(guide?'준비 확인에 동의해주세요':'사전 확인 동의 · 실제 요청 승인은 별도')+'</h4>'+(guide?'<p>'+esc(guide.consentNote)+'</p>':'')+outcome.preflightRequirements.map(row=>'<label class="check"><input type="checkbox" data-check-consent="'+esc(row.id)+'"> '+esc(guide?.consentLabels[row.id]||row.label)+'</label>').join('')+'<button data-operation data-connection-check-start>'+(guide?'준비 확인 시작':'사전 확인 시작')+'</button>');
   $('[data-connection-check-start]',root).onclick=()=>run(async()=>{if(connectionInputs.size&&[...connectionInputs.keys()].some(key=>key.startsWith(selected.id+'|')))throw Error('준비 정보가 바뀌었어요. 준비 확인을 다시 눌러주세요.');const approvals=Object.fromEntries($$('[data-check-consent]',root).map(input=>[input.dataset.checkConsent,input.checked]));if(Object.values(approvals).some(value=>!value))throw Error('아래 항목에 동의한 뒤 준비 확인 시작을 눌러주세요.');await view.call('startConnectionCheck',{connection:selected.id,token:outcome.token,approvals});renderOutcome();},'사전 확인 시작 · 문맥 전송·모델 요청 없음');
  }
